package webhook

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"queuelet/internal/store"
	"time"
)

func Ship(s *store.Store, now time.Time) error {
	rows, e := s.Rows(`SELECT * FROM webhook_outbox WHERE delivered_at IS NULL AND next_at <= $1 ORDER BY id LIMIT 20`, now)
	if e != nil {
		return e
	}
	for _, r := range rows {
		body, _ := json.Marshal(r["body"])
		mac := hmac.New(sha256.New, []byte(r["secret"].(string)))
		mac.Write(body)
		req, e := http.NewRequest("POST", r["url"].(string), bytes.NewReader(body))

		var resp *http.Response
		if e == nil {
			req.Header.Set("Content-Type", "application/json")
			req.Header.Set("X-Queuelet-Signature", hex.EncodeToString(mac.Sum(nil)))
			resp, e = (&http.Client{Timeout: 2 * time.Second}).Do(req)
		}
		status := 0
		message := ""
		if resp != nil {
			status = resp.StatusCode
		}
		if e != nil {
			message = e.Error()
		} else if status < 200 || status >= 300 {
			message = fmt.Sprintf("HTTP %d", status)
		}
		if message != "" {
			if resp != nil {
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
			}
			_, e = s.DB.Exec(`UPDATE webhook_outbox SET attempts=attempts+1,next_at=$2,event_at=$3,status=$4,error=$5 WHERE id=$1`, r["id"], now.Add(5*time.Second), now, status, message)
			if e != nil {
				return e
			}
			continue
		}
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
		_, e = s.DB.Exec(`UPDATE webhook_outbox SET delivered_at=$2,event_at=$2,attempts=attempts+1,status=$3,error='' WHERE id=$1`, r["id"], now, status)
		if e != nil {
			return e
		}
	}
	return nil
}
package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

func main() {
	var mu sync.Mutex
	mode := "ok"
	records := []map[string]any{}
	secret := os.Getenv("WEBHOOK_SECRET")
	if secret == "" {
		secret = "report-secret"
	}
	m := http.NewServeMux()
	m.HandleFunc("/admin/mode", func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		defer mu.Unlock()
		if r.Method == "POST" {
			var in struct {
				Mode string `json:"mode"`
			}
			json.NewDecoder(r.Body).Decode(&in)
			switch in.Mode {
			case "ok", "500", "slow", "timeout":
				mode = in.Mode
			default:
				http.Error(w, "unknown mode", 400)
				return
			}
		}
		json.NewEncoder(w).Encode(map[string]any{"mode": mode})
	})
	m.HandleFunc("/admin/records", func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		defer mu.Unlock()
		if r.Method == "DELETE" {
			records = []map[string]any{}
		}
		json.NewEncoder(w).Encode(map[string]any{"records": records})
	})
	m.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		b, _ := io.ReadAll(io.LimitReader(r.Body, 2<<20))
		mac := hmac.New(sha256.New, []byte(secret))
		mac.Write(b)
		sig, e := hex.DecodeString(r.Header.Get("X-Queuelet-Signature"))
		valid := e == nil && hmac.Equal(sig, mac.Sum(nil))
		mu.Lock()
		current := mode
		status := 200
		if current == "500" {
			status = 500
		}
		var body any
		if json.Unmarshal(b, &body) != nil {
			body = string(b)
		}
		records = append(records, map[string]any{"at": time.Now(), "body": body, "raw_body": string(b), "signature_valid": valid, "status": status})
		mu.Unlock()
		if !valid {
			log.Printf("signature did not verify")
		}
		if current == "slow" {
			time.Sleep(3 * time.Second)
		}
		if current == "timeout" {
			time.Sleep(10 * time.Second)
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		io.WriteString(w, `{"ok":true}`)
	})
	log.Fatal(http.ListenAndServe(":8201", m))
}
package schedule

import (
	"database/sql"
	"fmt"
	"github.com/robfig/cron/v3"
	"queuelet/internal/store"
	"time"
)

var parser = cron.NewParser(cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow)

func Next(expression, zone string, offset int, after time.Time) (time.Time, error) {
	s, e := parser.Parse(expression)
	if e != nil {
		return time.Time{}, e
	}
	loc, e := time.LoadLocation(zone)
	if e != nil {
		return time.Time{}, e
	}
	return s.Next(after.In(loc)), nil
}
func Offset(zone string, now time.Time) (int, error) {
	loc, e := time.LoadLocation(zone)
	if e != nil {
		return 0, e
	}
	_, offset := now.In(loc).Zone()
	return offset, nil
}
func Fire(s *store.Store, now time.Time) error {
	rows, e := s.Rows(`SELECT id FROM schedules WHERE enabled AND next_run_at <= $1 ORDER BY id`, now)
	if e != nil {
		return e
	}
	for _, r := range rows {
		if e = fireOne(s, r["id"], now); e != nil {
			return e
		}
	}
	return nil
}
func fireOne(s *store.Store, id any, now time.Time) error {
	tx, e := s.DB.Begin()
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var q, ns int64
	var kind, expression, zone string
	var payload []byte
	var due time.Time
	e = tx.QueryRow(`SELECT queue_id,namespace_id,kind,payload,cron,timezone,next_run_at FROM schedules WHERE id=$1 AND enabled AND next_run_at <= $2 FOR UPDATE`, id, now).Scan(&q, &ns, &kind, &payload, &expression, &zone, &due)
	if e == sql.ErrNoRows {
		return nil
	}
	if e != nil {
		return e
	}
	var paused bool
	var max int
	e = tx.QueryRow(`SELECT paused,max_attempts FROM queues WHERE id=$1`, q).Scan(&paused, &max)
	if e != nil {
		return e
	}
	next, e := Next(expression, zone, 0, now)
	if e != nil {
		return e
	}
	if !next.After(now) {
		return fmt.Errorf("schedule cannot advance")
	}
	// Advance even while paused. At most one due execution can catch up after downtime.
	if !paused {
		_, e = tx.Exec(`INSERT INTO jobs(queue_id,namespace_id,kind,payload,priority,state,run_at,max_attempts,created_at,event_at) VALUES($1,$2,$3,$4,5,'queued',$5,$6,$7,$7)`, q, ns, kind, string(payload), due, max, now)
		if e != nil {
			return e
		}
	}
	_, e = tx.Exec(`UPDATE schedules SET next_run_at=$2,last_run_at=CASE WHEN $3 THEN last_run_at ELSE $4 END WHERE id=$1`, id, next, paused, due)
	if e != nil {
		return e
	}
	return tx.Commit()
}
